-- KO-247: guided fill-blank and expanded, standalone Daily Focus practice bank.
-- Keep this curriculum content local/private; lesson content_variants are not used.

BEGIN;

-- Every legacy fill-blank now has the same guided-choice affordance as lesson quiz.
UPDATE daily_focus_questions
SET body = jsonb_set(body, '{options}', jsonb_build_array(body->>'answer', 'budget', 'risk', 'cash flow'), true)
WHERE type = 'fill_blank' AND NOT (body ? 'options');

UPDATE daily_focus_questions
SET body = jsonb_set(body, '{locales,en,options}', jsonb_build_array(body->'locales'->'en'->>'answer', 'budget', 'risk', 'cash flow'), true)
WHERE type = 'fill_blank' AND body->'locales' ? 'en' AND NOT (body->'locales'->'en' ? 'options');

UPDATE daily_focus_questions
SET body = jsonb_set(body, '{locales,id,options}', jsonb_build_array(body->'locales'->'id'->>'answer', 'anggaran', 'risiko', 'arus kas'), true)
WHERE type = 'fill_blank' AND body->'locales' ? 'id' AND NOT (body->'locales'->'id' ? 'options');

INSERT INTO daily_focus_questions (id, chapter, topic, difficulty, type, body, is_active) VALUES
('DF4-001', 'Foundation 0', 'financial_decisions', 'intermediate', 'multiple_choice', $$
{"type":"multiple_choice","difficulty":"intermediate","question":"You receive a Rp 2,000,000 bonus. Which choice best turns it into a financial buffer?","options":["Put it in a separate emergency-fund account","Spend it before the month ends","Use pay-later to buy more than the bonus","Lend it without a repayment plan"],"answer":"Put it in a separate emergency-fund account","explanation":"A windfall can strengthen resilience when it is separated before spending pressure takes over.","locales":{"id":{"type":"multiple_choice","difficulty":"intermediate","question":"Kamu menerima bonus Rp2.000.000. Pilihan mana yang paling membantu membangun penyangga keuangan?","options":["Masukkan ke rekening dana darurat terpisah","Habiskan sebelum bulan berakhir","Gunakan pay-later untuk membeli lebih banyak","Pinjamkan tanpa rencana pengembalian"],"answer":"Masukkan ke rekening dana darurat terpisah","explanation":"Bonus bisa memperkuat ketahanan keuangan jika dipisahkan sebelum muncul dorongan untuk berbelanja."}}
}$$::jsonb, true),
('DF4-002', 'Foundation 0', 'financial_decisions', 'intermediate', 'true_false', $$
{"type":"true_false","difficulty":"intermediate","question":"A higher salary can improve cash flow but still fail to build wealth if spending rises just as fast.","answer":true,"explanation":"Wealth grows from the gap between what comes in and what is retained in assets, not income alone.","locales":{"id":{"type":"true_false","difficulty":"intermediate","question":"Gaji yang lebih tinggi bisa memperbaiki arus kas, tetapi tetap tidak membangun kekayaan jika pengeluaran naik sama cepatnya.","answer":true,"explanation":"Kekayaan tumbuh dari selisih antara uang yang masuk dan yang disimpan menjadi aset, bukan dari pendapatan saja."}}
}$$::jsonb, true),
('DF4-003', 'Money Life Skills', 'financial_decisions', 'intermediate', 'fill_blank', $$
