('DF4-005', 'Plan Your Money', 'financial_decisions', 'intermediate', 'select_all', $$
{"type":"select_all","difficulty":"intermediate","question":"Select ALL questions worth asking before a large purchase.","options":["Is it planned and affordable?","What goal would this delay?","What is the total cost including fees?","Will a countdown timer make the decision for me?"],"answer":["Is it planned and affordable?","What goal would this delay?","What is the total cost including fees?"],"explanation":"A short pause exposes trade-offs, total cost, and whether the purchase fits the plan.","locales":{"id":{"type":"select_all","difficulty":"intermediate","question":"Pilih SEMUA pertanyaan yang layak ditanyakan sebelum pembelian besar.","options":["Apakah pembelian ini terencana dan terjangkau?","Tujuan apa yang mungkin tertunda?","Berapa total biaya termasuk biaya tambahan?","Apakah penghitung waktu harus menentukan keputusan saya?"],"answer":["Apakah pembelian ini terencana dan terjangkau?","Tujuan apa yang mungkin tertunda?","Berapa total biaya termasuk biaya tambahan?"],"explanation":"Jeda singkat membantu melihat trade-off, total biaya, dan kecocokan dengan rencana."}}
