('DF4-006', 'Plan Your Money', 'financial_decisions', 'intermediate', 'ordering', $$
{"type":"ordering","difficulty":"intermediate","question":"Order the steps for turning an irregular annual bill into a monthly plan.","options":["Estimate the annual total","Divide it across the months","Open or label a separate fund","Transfer the monthly amount","Pay from that fund when due"],"answer":["Estimate the annual total","Divide it across the months","Open or label a separate fund","Transfer the monthly amount","Pay from that fund when due"],"explanation":"Planning before the due date turns a surprise-looking bill into a manageable routine.","locales":{"id":{"type":"ordering","difficulty":"intermediate","question":"Urutkan langkah mengubah tagihan tahunan yang tidak rutin menjadi rencana bulanan.","options":["Perkirakan total tahunan","Bagi total ke beberapa bulan","Buka atau beri label rekening terpisah","Transfer jumlah bulanan","Bayar dari dana itu saat jatuh tempo"],"answer":["Perkirakan total tahunan","Bagi total ke beberapa bulan","Buka atau beri label rekening terpisah","Transfer jumlah bulanan","Bayar dari dana itu saat jatuh tempo"],"explanation":"Perencanaan sebelum jatuh tempo membuat tagihan yang terlihat mendadak menjadi rutinitas yang terkelola."}}
