}$$::jsonb, true),
('DF4-008', 'Grow Your Money', 'financial_decisions', 'advanced', 'multiple_choice', $$
{"type":"multiple_choice","difficulty":"advanced","question":"Two funds track the same market. Fund A charges 0.2% yearly and Fund B charges 1.5%. What should you compare next?","options":["Whether their holdings and tracking quality are genuinely comparable","Only the fund with the higher fee","Which logo looks more professional","Whether either fund guarantees profit"],"answer":"Whether their holdings and tracking quality are genuinely comparable","explanation":"A fee comparison matters only after confirming the products provide a comparable exposure and service.","locales":{"id":{"type":"multiple_choice","difficulty":"advanced","question":"Dua reksa dana mengikuti pasar yang sama. Dana A mengenakan 0,2% per tahun dan Dana B 1,5%. Apa yang perlu dibandingkan berikutnya?","options":["Apakah isi dan kualitas pelacakannya benar-benar sebanding","Hanya dana dengan biaya lebih tinggi","Logo mana yang terlihat lebih profesional","Apakah salah satunya menjamin keuntungan"],"answer":"Apakah isi dan kualitas pelacakannya benar-benar sebanding","explanation":"Perbandingan biaya baru bermakna setelah memastikan produk memberi eksposur dan layanan yang sebanding."}}
}$$::jsonb, true),
